    "correctIndex": 0,
    "hintEn": "Molar mass of $\\text{Fe}_2\\text{O}_3 = 2(56) + 3(16) = 112 + 48 = 160\\text{ g/mol}$. Percentage of $\\text{Fe} = \\frac{2 \\times 56}{160} \\times 100\\%$.",
    "hintAr": "الكتلة المولية لـ $\\text{Fe}_2\\text{O}_3 = 2(56) + 3(16) = 160\\text{ جم/مول}$. النسبة المئوية للحديد = $\\frac{112}{160} \\times 100\\%$.",
    "stepByStepSolutionEn": [
      "Molar mass of $\\text{Fe}_2\\text{O}_3 = (2 \\times 56) + (3 \\times 16) = 112 + 48 = 160\\text{ g/mol}$.",
      "Mass of iron in one mole: $2 \\times 56 = 112\\text{ g}$.",
      "$$\\%\\text{Fe} = \\frac{112}{160} \\times 100\\% = 70.0\\%$$"
    ],
    "stepByStepSolutionAr": [
      "الكتلة المولية لمركب $\\text{Fe}_2\\text{O}_3 = (2 \\times 56) + (3 \\times 16) = 160\\text{ جم/مول}$.",
      "كتلة الحديد في مول واحد = $112\\text{ جم}$.",
      "$$\\%\\text{Fe} = \\frac{112}{160} \\times 100\\% = 70.0\\%$$"
    ],
    "teacherTipEn": "In Egyptian raw iron ores, roasting raises the iron percentage up to $69.6\\%$ by expelling moisture and carbon dioxide ($2\\text{FeCO}_3 + \\frac{1}{2}\\text{O}_2 \\to \\text{Fe}_2\\text{O}_3 + 2\\text{CO}_2$).",
    "teacherTipAr": "في الخامات المصرية، يؤدي التحميص إلى رفع نسبة الحديد لتصل إلى حوالي $69.6\\%$ نتيجة طرد الرطوبة وغاز ثاني أكسيد الكربون."
